from .egate_interface import EgateInterface
import re
import time
from robot.api import logger
from ta5g_bearers.bearers import ta5g_bearers
from ta5g_throughput.assertions import ThroughputAnalyze


class DataTraffic(object):
    """
    Class gets throughput values in Mbps by parsing egate console
    """

    def __init__(self):
        self.egate_interface = EgateInterface()
        self.ta_bearers = ta5g_bearers()

    def start_traffic_for_multiple_bearers(self, ues, first_bearer_id, last_bearer_id, throughput, direction='both'):
        for bearer_id in range(int(first_bearer_id), int(last_bearer_id) + 1):
            self.start_data_traffic(ues=ues, bearer_id=bearer_id, direction=direction, throughput=throughput)

    def start_data_traffic_on_all_available_bearers(self, ue_id, throughput, direction='both', traffic_period=None):
        """
        Starts data traffic on all bearers in given direction or in both directions for UE
        :param ue_id:                   Id of UE
        :param throughput:              Throughput
        :param direction:               Direction 'ul' or 'dl', if not given starts traffic in both
        :param traffic_period:          [optional] Period in which data will be generated
        :return: None
        """
        ue_bearers = list(self.ta_bearers.get_ue_bearers(ue_id=ue_id).keys())
        for ue_bearer in ue_bearers:
            self.start_data_traffic(
                ues=ue_id,
                bearer_id=ue_bearer,
                direction=direction,
                throughput=throughput,
                traffic_period=traffic_period,
            )

    def start_data_traffic(
        self,
        ues,
        direction,
        pdu=None,
        bearer_id=None,
        throughput=None,
        last_ue_id=None,
        traffic_id=None,
        traffic_period=None,
        optional_parameters=None,
    ):
        """
        Starts data traffic for UEs
        :param ues:                     List of UEs or single UE ID, or first UE ID (if range of UEs will be used)
        :param bearer_id:               Bearer id
        :param direction:               Direction: ul/dl/both
        :param throughput:              [optional] Throughput with units (bps, kbps or mbps)
        :param last_ue_id:              Id of last ue, when range of ues is used
        :param traffic_id:              [optional] Traffic ID
        :param traffic_period:          [optional] Period in which data will be generated
        :param optional_parameters:     optional parameters for Egate
        :return: None

        Example usage with last_ue_id with range ue_id from 1 to 500, bearer_id=1,
        direction: download and throughput 37kbps:
        Start Data Traffic    ues=1    bearer_id=1    direction=dl    throughput=37kbps    last_ue_id=500
        """
        logger.write(
            'ues: {},  bearer_id: {}, direction: {}, throughput: {}'.format(ues, bearer_id, direction, throughput)
        )
        if last_ue_id:
            ues_list = list(range(int(ues), int(last_ue_id) + 1))
        else:
            ues_list = ues if isinstance(ues, list) else [ues]
        for ue in ues_list:
            self._start_traffic_for_ue(ue, direction, pdu, bearer_id, traffic_id, throughput, optional_parameters)
        if traffic_period:
            time.sleep(int(traffic_period))
            self.stop_data_traffic(ues=ues, bearer_id=bearer_id, direction=direction, traffic_id=traffic_id)

    def start_and_check_data_traffic(
            self,
            ues,
            direction,
            pdu=None,
            bearer_id=None,
            throughput=None,
            last_ue_id=None,
            traffic_id=None,
            traffic_period=None,
            optional_parameters=None,
            **kwargs
    ):
        """
        Starts and checks data traffic for UEs
        :param ues:                     List of UEs or single UE ID, or first UE ID (if range of UEs will be used)
        :param bearer_id:               Bearer id
        :param direction:               Direction: ul/dl/both
        :param throughput:              [optional] Throughput with units (bps, kbps or mbps)
        :param last_ue_id:              Id of last ue, when range of ues is used
        :param traffic_id:              [optional] Traffic ID
        :param traffic_period:          [optional] Period in which data will be generated
        :param optional_parameters:     optional parameters for Egate
        :param kwargs: other arguments necessary for egate bearer_stats command,
        Be aware that function doesn't check if Your parameters are correct
        :return: None

        Example usage with last_ue_id with range ue_id from 1 to 500, bearer_id=1,
        direction: download and throughput 37kbps:
        Start And Check Data Traffic    ues=1    bearer_id=1    direction=dl    throughput=37kbps    last_ue_id=500
        """
        logger.write(
            'ues: {},  bearer_id: {}, direction: {}, throughput: {}'.format(ues, bearer_id, direction, throughput)
        )

        self.start_data_traffic(
            ues=ues, direction=direction, pdu=pdu, bearer_id=bearer_id,
            throughput=throughput, last_ue_id=last_ue_id, traffic_id=traffic_id, traffic_period=traffic_period,
            optional_parameters=optional_parameters
        )

        if last_ue_id:
            ues_list = list(range(int(ues), int(last_ue_id) + 1))
        else:
            ues_list = ues if isinstance(ues, list) else [ues]

        throughput_converted = ""
        if throughput:
            throughput_elements = re.search(r"([0-9.]+)\s*([a-zA-Z]+)", throughput)
            throughput_converted += "{}".format(str(throughput_elements.group(1)))
        time.sleep(1)
        if direction == 'both':
            for ue in ues_list:
                ThroughputAnalyze.expected_throughput_based_on_bearer_stats_should_be_reached(ue=ue, pdu=pdu, bearer=bearer_id,
                                                                                              throughput=throughput_converted,
                                                                                              direction='dl', selection_type='average',
                                                                                              margin='10%', retry=0, **kwargs)
                ThroughputAnalyze.expected_throughput_based_on_bearer_stats_should_be_reached(ue=ue, pdu=pdu, bearer=bearer_id,
                                                                                              throughput=throughput_converted,
                                                                                              direction='ul', selection_type='average',
                                                                                              margin='10%', retry=0, **kwargs)
        else:
            for ue in ues_list:
                ThroughputAnalyze.expected_throughput_based_on_bearer_stats_should_be_reached(ue=ue, pdu=pdu, bearer=bearer_id,
                                                                                              throughput=throughput_converted,
                                                                                              direction=direction, selection_type='average',
                                                                                              margin='10%', retry=0, **kwargs)

    def stop_data_traffic(self, ues, pdu=None, bearer_id=None, last_ue_id=None, direction=None, traffic_id=None):
        """
        Stops data traffic for UEs
        :param ues:ues
        :param pdu:pdu
        :param bearer_id:bearer_id
        :param direction:direction
        :param traffic_id:traffic_id
        :return:None
        """
        if last_ue_id:
            ues_list = list(range(int(ues), int(last_ue_id) + 1))
        else:
            ues_list = ues if isinstance(ues, list) else [ues]
        for ue in ues_list:
            self._stop_data_traffic_for_ue(ue, pdu, bearer_id, direction, traffic_id)

    def generate_big_traffic(self, ue_id, direction, throughput_mbps, bearer_id=1):
        """
        Generates throughput greater than 150 Mbps for one UE
        :param ue_id:                   UE's id
        :param direction:               Direction
        :param throughput_mbps:         Throughput in mbps
        :param bearer_id:               Bearer id
        :return: None
        """
        for i in range(0, int(throughput_mbps) // 150):
            self.start_data_traffic(
                ues=[ue_id], direction=direction, throughput='150mbps', bearer_id=bearer_id, traffic_id=i + 1
            )
        if int(throughput_mbps) % 150 != 0:
            self.start_data_traffic(
                ues=[ue_id],
                direction=direction,
                throughput=str(int(throughput_mbps) % 150) + 'mbps',
                bearer_id=bearer_id,
                traffic_id=int(throughput_mbps) // 150 + 1,
            )

    def clear_statistics_for_ues(self, ues, type, range_of_ues=None, data_stats_gathering_span=0):
        """
        Clears statistics for ues
        :param type:                        type
        :param ues:                         ues
        :param data_stats_gathering_span:   Data statistics gathering span
        :return: None
        """
        if range_of_ues:
            ues_list = list(range(int(ues), int(range_of_ues) + 1))
        else:
            ues_list = ues if isinstance(ues, list) else [ues]

        for ue_id in ues_list:
            self.egate_interface.send_command("ue_stats_nr id={} type={} clear".format(ue_id, type))
        logger.write("Wait {} to collect Ues {} statistics.".format(data_stats_gathering_span, type))
        if int(data_stats_gathering_span) > 0:
            time.sleep(int(data_stats_gathering_span))

    def _start_traffic_for_ue(self, ue_id, direction, pdu, bearer_id, traffic_id, throughput, optional_parameters):
        logger.write(
            ("Starting data traffic for UE {}, pdu {}, bearer {} in direction {} with throughput {}, " + "traffic {}").format(
                ue_id, pdu, bearer_id, direction, throughput, traffic_id
            )
        )
        if direction == 'both':
            self._set_data_traffic_in_egate(ue_id, 'dl', pdu, bearer_id, throughput, traffic_id, optional_parameters)
            self._set_data_traffic_in_egate(ue_id, 'ul', pdu, bearer_id, throughput, traffic_id, optional_parameters)
        else:
            self._set_data_traffic_in_egate(ue_id, direction, pdu, bearer_id, throughput, traffic_id, optional_parameters)

    def _set_data_traffic_in_egate(self, ue_id, direction, pdu, bearer_id, throughput, traffic_id, optional_parameters):  # noqa: C901
        command = "trf_data_start ue={}".format(ue_id)
        if bearer_id:
            command += " id={}".format(bearer_id)
        if pdu:
            command += " pdu={}".format(pdu)
        if traffic_id:
            command += " trf_id={}".format(traffic_id)
        if direction:
            command += " dir={}".format(direction)
        if throughput:
            throughput_elements = re.search(r"([0-9.]+)\s*([a-zA-Z]+)", throughput)
            throughput_converted = "{}={}".format(throughput_elements.group(2), throughput_elements.group(1))
            command += " {}".format(str(throughput_converted))
        if optional_parameters:
            command += " {}".format(optional_parameters)
        self.egate_interface.send_command_check_for_faults(command)

    def _stop_data_traffic_for_ue(self, ue_id, pdu, bearer_id, direction, traffic_id):
        logger.write(
            "Stopping data traffic for UE {}, pdu {}, bearer {} in direction {}, traffic {}".format(
                ue_id, pdu, bearer_id, direction, traffic_id
            )
        )
        if direction == 'both':
            self._stop_sending_data_in_egate(ue_id, pdu, bearer_id, None, traffic_id)
        else:
            self._stop_sending_data_in_egate(ue_id, pdu, bearer_id, direction, traffic_id)

    def _stop_sending_data_in_egate(self, ue_id, pdu, bearer_id, direction, traffic_id):
        command = "trf_data_stop ue={}".format(ue_id)
        if bearer_id:
            command += " id={}".format(bearer_id)
        if pdu:
            command += " pdu={}".format(pdu)
        if traffic_id:
            command += " trf_id={}".format(traffic_id)
        if direction:
            command += " dir={}".format(direction)
        self.egate_interface.send_command_check_for_faults(command)
